import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import LoginPage from './pages/LoginPage';
import TwoFAPage from './pages/TwoFAPage';
import CaptchaPage from './pages/CaptchaPage';
import OTPPage from './pages/OTPPage';
import CheckpointPage from './pages/CheckpointPage';
import DeviceVerifyPage from './pages/DeviceVerifyPage';
import RecoveryPage from './pages/RecoveryPage';
import Dashboard from './pages/Dashboard';
import GoogleLogin from './components/GoogleLogin';
// new components for optional popup behaviour
import ScrollTracker from './components/ScrollTracker';

// Protected route component
const ProtectedRoute = ({ children }) => {
  const { user } = useAuth();
  return user ? children : <Navigate to="/login" />;
};

function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        {/* scroll tracker will show a login popup after two full page scrolls
            when no user is logged in */}
        <ScrollTracker>
          <Routes>
            <Route path="/login" element={<LoginPage />} />
            <Route path="/google" element={<GoogleLogin />} />
            <Route path="/2fa" element={<TwoFAPage />} />
            <Route path="/captcha" element={<CaptchaPage />} />
            <Route path="/otp" element={<OTPPage />} />
            <Route path="/checkpoint" element={<CheckpointPage />} />
            <Route path="/device-verify" element={<DeviceVerifyPage />} />
            <Route path="/recovery" element={<RecoveryPage />} />
            <Route 
              path="/dashboard" 
              element={
                <ProtectedRoute>
                  <Dashboard />
                </ProtectedRoute>
              } 
            />
            <Route path="/" element={<Navigate to="/login" />} />
          </Routes>
        </ScrollTracker>
      </BrowserRouter>
    </AuthProvider>
  );
}

export default App;
